//! Shelf tools: small helpers for the library's shelves.

/// Returns how many shelves `books` books need,
/// when each shelf holds `per_shelf` books.
///
/// A shelf that is only part full still counts.
///
/// # Examples
///
/// ```
/// assert_eq!(shelves_needed(25, 10), 3);
/// ```
fn shelves_needed(books: u32, per_shelf: u32) -> u32 {
    books.div_ceil(per_shelf)
}

fn main() {
    println!("25 books: {} shelves", shelves_needed(25, 10));
    println!("30 books: {} shelves", shelves_needed(30, 10));
}

